sub landuse_readParams {
    my ($j, $tok, $ntoks) = @_;
    my ($id);
    if ($ntoks < 1) {
        return error_setInpError(203, $L0);
    }
    $id = project_findID(5, $tok->[0]);
    if (!defined($id)) {
        return error_setInpError(209, $tok->[0]);
    }
    $Landuse->[$j]->[TLanduse_ID] = $id;
    if ($ntoks > 1) {
        if ($ntoks < 4) {
            return error_setInpError(203, $L0);
        }
        if (!(getDouble($tok->[1], $Landuse->[$j]->[TLanduse_sweepInterval]) != 0)) {
            return error_setInpError(211, $tok->[1]);
        }
        if (!(getDouble($tok->[2], $Landuse->[$j]->[TLanduse_sweepRemoval]) != 0)) {
            return error_setInpError(211, $tok->[2]);
        }
        if (!(getDouble($tok->[3], $Landuse->[$j]->[TLanduse_sweepDays0]) != 0)) {
            return error_setInpError(211, $tok->[3]);
        }
    } else {
        $Landuse->[$j]->[TLanduse_sweepInterval] = 0.0;
        $Landuse->[$j]->[TLanduse_sweepRemoval] = 0.0;
        $Landuse->[$j]->[TLanduse_sweepDays0] = 0.0;
    }
    if (($Landuse->[$j]->[TLanduse_sweepRemoval] < 0.0) || ($Landuse->[$j]->[TLanduse_sweepRemoval] > 1.0)) {
        return error_setInpError(211, $tok->[2]);
    }
    return 0;
}

