sub qualrout_init {
    my ($i, $p, $isWet, $c);
    $i = 0;
    $p = 0;
    $isWet = 0;
    $c = 0.0;
    for ($i = 0; $i < $Nobjects->[2]; $i++) {
        $isWet = ($Node->[$i]->[TNode_newDepth] > $ZeroDepth) ? 1 : 0;
        for ($p = 0; $p < $Nobjects->[4]; $p++) {
            $c = 0.0;
            if ($isWet != 0) {
                $c = $Pollut->[$p]->[TPollut_initConcen];
            }
            $Node->[$i]->[TNode_oldQual]->[$p] = $c;
            $Node->[$i]->[TNode_newQual]->[$p] = $c;
        }
    }
    for ($i = 0; $i < $Nobjects->[3]; $i++) {
        $isWet = ($Link->[$i]->[TLink_newDepth] > $ZeroDepth) ? 1 : 0;
        for ($p = 0; $p < $Nobjects->[4]; $p++) {
            $c = 0.0;
            if ($isWet != 0) {
                $c = $Pollut->[$p]->[TPollut_initConcen];
            }
            $Link->[$i]->[TLink_oldQual]->[$p] = $c;
            $Link->[$i]->[TLink_newQual]->[$p] = $c;
        }
    }
}

# qualrout.c:100
sub qualrout_execute {
    my ($tStep) = @_;
    my ($i, $j, $qIn, $vAvg);
    $i = 0;
    $j = 0;
    $qIn = 0.0;
    $vAvg = 0.0;
    for ($i = 0; $i < $Nobjects->[3]; $i++) {
        findLinkMassFlow($i, $tStep);
    }
    for ($j = 0; $j < $Nobjects->[2]; $j++) {
        $Node->[$j]->[TNode_qualInflow] = $Node->[$j]->[TNode_inflow];
        $qIn = $Node->[$j]->[TNode_qualInflow];
        $vAvg = (($Node->[$j]->[TNode_oldVolume] + $Node->[$j]->[TNode_newVolume]) || rt_za($Node->[$j]->[TNode_oldVolume], $Node->[$j]->[TNode_newVolume])) / 2.0;
        if (defined($Node->[$j]->[TNode_treatment])) {
            if ($qIn < 1e-10) {
                $qIn = 0.0;
            }
            treatmnt_setInflow($qIn, $Node->[$j]->[TNode_newQual]);
        }
        if (($Node->[$j]->[TNode_type] == 2) || ($Node->[$j]->[TNode_oldVolume] > $ZeroVolume)) {
            findStorageQual($j, $tStep);
        } else {
            findNodeQual($j);
        }
        if (defined($Node->[$j]->[TNode_treatment])) {
            treatmnt_treat($j, $qIn, $vAvg, $tStep);
        }
    }
    for ($i = 0; $i < $Nobjects->[3]; $i++) {
        findLinkQual($i, $tStep);
    }
}

