sub getMixedQual {
    my ($c, $v1, $wIn, $qIn, $tStep) = @_;
    my ($vIn, $cIn, $cMax, $__a1, $__b2, $__a3, $__d4);
    if ($qIn <= 1e-10) {
        return $c;
    }
    $vIn = ($qIn * $tStep) || rt_zm($qIn, $tStep);
