sub createRdiiFile {
    my ($hasRdii, $elapsedTime, $duration, $currentDate);
    $hasRdii = 0;
    $elapsedTime = 0.0;
    $duration = 0.0;
    $currentDate = 0.0;
    $RdiiStep = $WetStep;
    $NumRdiiNodes = getNumRdiiNodes();
    if ($NumRdiiNodes == 0) {
        $Frdii->[TFile_mode] = 0;
        return;
    } elsif ($Frdii->[TFile_mode] == 0) {
        $Frdii->[TFile_mode] = 1;
    }
    validateRdii();
    initGageData();
    if ($ErrorCode != 0) {
        return;
    }
    openRdiiProcessor();
    if (!($ErrorCode != 0)) {
        initUnitHydData();
        $duration = $TotalDuration / 1000.0;
        $elapsedTime = 0.0;
        while (($elapsedTime <= $duration) && (!($ErrorCode != 0))) {
            $currentDate = ($StartDateTime + ($elapsedTime / 86400.0)) || rt_za($StartDateTime, ($elapsedTime / 86400.0));
            getRainfall($currentDate);
            getUnitHydRdii($currentDate);
            $hasRdii = getNodeRdii();
            if ($hasRdii != 0) {
                saveRdiiFlows($currentDate);
            }
            $elapsedTime = $elapsedTime + $RdiiStep;
        }
    }
    closeRdiiProcessor();
}

