                $tLimb = rt_i32($UnitHyd->[$i]->[TUnitHyd_tPeak]->[$m]->[$k]);
                $ri = ($ri <= $tLimb) ? $ri : $tLimb;
                $tLimb = rt_i32(($UnitHyd->[$i]->[TUnitHyd_tBase]->[$m]->[$k] - $tLimb));
                if ($tLimb > 0) {
