sub report_writeMaxStats {
    my ($maxMassBalErrs, $maxCourantCrit, $nMaxStats) = @_;
    my ($i, $j, $k);
    $i = 0;
    $j = 0;
    if (($RouteModel != 4) || ($Nobjects->[3] == 0)) {
        return;
    }
    if ($nMaxStats <= 0) {
        return;
    }
    if ($maxMassBalErrs->[0]->[TMaxStats_index] >= 0) {
        report_writeLine($L0);
        report_writeLine($L470);
        report_writeLine($L471);
        report_writeLine($L470);
        for ($i = 0; $i < $nMaxStats; $i++) {
            $j = $maxMassBalErrs->[$i]->[TMaxStats_index];
            if ($j < 0) {
                next;
            }
            c_fprintf($Frpt->[TFile_file], $L472, $Node->[$j]->[TNode_ID], $maxMassBalErrs->[$i]->[TMaxStats_value]);
        }
        report_writeLine($L0);
    }
    if ($CourantFactor == 0.0) {
        return;
    }
    report_writeLine($L0);
    report_writeLine($L473);
    report_writeLine($L474);
    report_writeLine($L473);
    $k = 0;
    for ($i = 0; $i < $nMaxStats; $i++) {
        $j = $maxCourantCrit->[$i]->[TMaxStats_index];
        if ($j < 0) {
            next;
        }
        $k++;
        if ($maxCourantCrit->[$i]->[TMaxStats_objType] == 2) {
            c_fprintf($Frpt->[TFile_file], $L475, $Node->[$j]->[TNode_ID]);
        } else {
            c_fprintf($Frpt->[TFile_file], $L476, $Link->[$j]->[TLink_ID]);
        }
        c_fprintf($Frpt->[TFile_file], $L477, $maxCourantCrit->[$i]->[TMaxStats_value]);
    }
    if ($k == 0) {
        c_fprintf($Frpt->[TFile_file], $L478);
    }
    report_writeLine($L0);
}

