    $totalRoutingTime = ($timeStepStats->[TTimeStepStats_steadyStateTime] + $timeStepStats->[TTimeStepStats_routingTime]) || rt_za($timeStepStats->[TTimeStepStats_steadyStateTime], $timeStepStats->[TTimeStepStats_routingTime]);
    if ($totalRoutingTime > 0.0) {
        $fSteadyState = $totalRoutingTime == 0.0 ? rt_fdiv0(((100.0 * $timeStepStats->[TTimeStepStats_steadyStateTime]) || rt_zm(100.0, $timeStepStats->[TTimeStepStats_steadyStateTime])), $totalRoutingTime) : ((100.0 * $timeStepStats->[TTimeStepStats_steadyStateTime]) || rt_zm(100.0, $timeStepStats->[TTimeStepStats_steadyStateTime])) / $totalRoutingTime;
    }
    report_writeLine($L0);
    report_writeLine($L470);
    report_writeLine($L486);
    report_writeLine($L470);
    c_fprintf($Frpt->[TFile_file], $L487, $timeStepStats->[TTimeStepStats_minTimeStep]);
    c_fprintf($Frpt->[TFile_file], $L488, ($timeStepCount == 0.0 ? rt_fdiv0($timeStepStats->[TTimeStepStats_routingTime], $timeStepCount) : $timeStepStats->[TTimeStepStats_routingTime] / $timeStepCount));
    c_fprintf($Frpt->[TFile_file], $L489, $timeStepStats->[TTimeStepStats_maxTimeStep]);
    c_fprintf($Frpt->[TFile_file], $L490, (($fSteadyState <= 100.0) ? $fSteadyState : 100.0));
    c_fprintf($Frpt->[TFile_file], $L491, ($timeStepCount == 0.0 ? rt_fdiv0($timeStepStats->[TTimeStepStats_trialsCount], $timeStepCount) : $timeStepStats->[TTimeStepStats_trialsCount] / $timeStepCount));
    c_fprintf($Frpt->[TFile_file], $L492, ($timeStepCount == 0.0 ? rt_fdiv0(((100.0 * $NonConvergeCount) || rt_zm(100.0, $NonConvergeCount)), $timeStepCount) : ((100.0 * $NonConvergeCount) || rt_zm(100.0, $NonConvergeCount)) / $timeStepCount));
    if (($RouteModel == 4) && ($CourantFactor > 0.0)) {
        report_RouteStepFreq($timeStepStats);
