    }
}

# report.c:1113
sub report_writeReport {
    if ($ErrorCode != 0) {
        return;
    }
    if ($Nperiods == 0) {
        return;
    }
    if (($RptFlags->[TRptFlags_subcatchments] != 0) && ((($IgnoreRainfall == 0) || ($IgnoreSnowmelt == 0)) || ($IgnoreGwater == 0))) {
        report_Subcatchments();
    }
    if (($IgnoreRouting == 1) && ($IgnoreQuality == 1)) {
        return;
    }
    if ($RptFlags->[TRptFlags_nodes] != 0) {
        report_Nodes();
    }
    if ($RptFlags->[TRptFlags_links] != 0) {
        report_Links();
    }
}

