            while (($j >= 0) && ($Event->[$j]->[TEvent_start] > $temp->[TEvent_start])) {
                $Event->[($j + $gap)] = clone_TEvent($Event->[$j]);
                $j -= $gap;
            }
            if ($j != ($i - $gap)) {
                $Event->[($j + $gap)] = clone_TEvent($temp);
            }
        }
    }
    for ($i = 0; $i < ($NumEvents - 1); $i++) {
        if ($Event->[$i]->[TEvent_end] > $Event->[($i + 1)]->[TEvent_start]) {
