        undef;
        $NodeStats = undef;
    }
    if (defined($LinkStats)) {
        undef;
        $LinkStats = undef;
    }
    if (defined($StorageStats)) {
        undef;
        $StorageStats = undef;
    }
    if (defined($OutfallStats)) {
        for ($j = 0; $j < $Nnodes->[1]; $j++) {
            if (defined($OutfallStats->[$j]->[TOutfallStats_totalLoad])) {
                undef;
                $OutfallStats->[$j]->[TOutfallStats_totalLoad] = undef;
            }
        }
        if (defined($OutfallStats)) {
