    while ($First <= $Last) {
        $i1 = $Stack->[$First];
        $k1 = $StartPos->[$i1];
        $k2 = $k1 + $Node->[$i1]->[TNode_degree];
        for ($k = $k1; $k < $k2; $k++) {
